quests[46665] = { id = 46665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46666] = { id = 46666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volltreffer", description = "Pst... Kommt mal her! Ich habe gerade einen Tipp gekriegt, dass eine Höhle auf dieser Insel prall gefüllt mit Schätzen ist! Das könnte mein größter Fund überhaupt werden.\n\nDas Problem ist nur, ich hab... mir meinen Fuß verstaucht. Ich würde mich ja gerne gemeinsam mit Euch in den Kampf gegen die Dämonen schwingen, doch... ich soll mein Bein nicht belasten. So ein Mist.\n\nWie wäre es, wenn Ihr die Höhle durchsucht und Euch wieder bei mir meldet? Ich werde den Höhleneingang auf Eurer Karte markieren. Mir wurde gesagt, er ist recht gut versteckt, also werdet Ihr Euch ein wenig umsehen müssen.", sourceObjective = "Untersucht die Höhle, von der Ausgräberin Karla Euch erzählt hat.", progress = "Habt Ihr etwas gefunden?", completion = "Da haben wir ja einen Volltreffer gelandet! Jetzt brauchen wir nur noch einen Schlüssel... hm. Warum arbeitet Ihr nicht daran, die Schlüssel für diese Truhen zu beschaffen, und ich bleib hier bei der alten Torfnase?", sourceObjectiveStatus = "unverified-source-field" }
quests[46674] = { id = 46674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erhaltung der Natur", description = "Ich fürchte, dieser Angriff auf Goldrinn ist nur der Anfang, {name}. Der Befehlshaber muss gefunden und beseitigt werden.\n\nWar Thisalee nicht bei Euch? Sie ist nie zurückgekehrt... So ein freches Kind. Vermutlich ist sie schon an der Verheerten Küste und versucht, diesen Kommandanten aufzuspüren. Bitte findet sie und lasst nicht zu, dass sie das alleine in Angriff nimmt.", sourceObjective = "Findet Thisalee Krähe nahe der Retterklippe an der Verheerten Küste.", completion = "Seht, wie er sich windet. Er hat schnell aufgegeben!", sourceObjectiveStatus = "unverified-source-field" }
quests[46675] = { id = 46675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Fährte des Dämons", description = "Ich habe die Initiative ergriffen und mich ein wenig umgesehen, bevor ich mir diese Wyrmzunge gegriffen habe. Anscheinend verschanzen sich ihre Streitmächte in einem Lager am Wichtelpeinvorstoß. Ich hatte allerdings Schwierigkeiten, herauszufinden, wer ihr Kommandant ist und ob er sich in der Nähe aufhält.\n\nWenn er von einem anderen Ort aus die Zügel in der Hand hält, müssen die Truppen Befehle bei sich tragen. Lasst uns sehen, ob wir welche finden können... bei ihren Leichen!", sourceObjective = "Sammelt 3 Wichtelpeinbriefe von Dämonen am Wichtelpeinvorstoß.", progress = "Wenn wir ein paar der Briefe beisammen haben, sollte es mir möglich sein, die Position des Kommandanten herauszufinden.", completion = "Lasst mich einen Blick darauf werfen... Ich glaube, ich hab's!", sourceObjectiveStatus = "unverified-source-field" }
quests[46676] = { id = 46676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Natur", description = "Wie es scheint, sind wir nicht die einzigen Druiden, die Bekanntschaft mit diesen Dämonen gemacht haben. Die Legion hat eine Menge Gefangene genommen und sie in ihr Lager zurückgebracht. Unsere Brüder und Schwestern sind verwundet und leiden...\n\nIhr könnt heilen! Also lasst sie uns retten!", sourceObjective = "Heilt 5 verletzte Druiden am Wichtelpeinvorstoß.", progress = "Wir dürfen nicht zulassen, dass die anderen Druiden weiter leiden!", completion = "Es geht mir sehr viel besser in dem Wissen, dass wir einige der anderen Druiden retten konnten. Wir haben getan, was in unserer Macht stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[46677] = { id = 46677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stich einer Distel", description = "Der Kommandant heißt Katith'rax. Er hat diese Angriffe organisiert und ist jetzt ihr Anführer. Zum Glück scheint er nicht sehr weit weg zu sein.\n\nDirekt vor der Küste liegt eine kleine Insel. Anscheinend versteckt er sich dort und bellt Befehle, ohne sich selbst die Hände schmutzig zu machen.\n\nIch wiederum habe nichts dagegen, mir die Hände ein wenig schmutzig zu machen. Und wie sieht es mit Euch aus?", sourceObjective = "Tötet Kommandant Katith'rax auf der Dunkelsteininsel.", completion = "Rache fühlt sich gut an.\n\nAber die Angriffe auf die Ahnen zu stoppen ist noch besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[46678] = { id = 46678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende der Fäden", description = "Das Schneiderhandwerk gehört zu den vornehmsten Berufen, denn Kleider brauchen alle. Die meisten Leute kleiden sich gänzlich unbewusst. Aber die Betrachtung der Legenden zeigt, dass es zwischen den Völkern gewaltige Unterschiede gibt.\n\nUnd die Nachtgeborenen sind Meister des guten Kleidungsstils! Ein Großteil ihrer Brillanz ist den Materialien geschuldet, wie dem Faden und dem Webstuhl. Wir werden uns beides zunutze machen. Doch bevor Ihr Materialien beschafft, muss ich meine Liste überprüfen. Sucht nach dem Modeblatt, das ich mitgebracht hatte. Vielleicht habe ich es beim Flugmeister fallen lassen?", sourceObjective = "Bringt Eliezer sein verlorenes Exemplar von \"Nächte mit den Nachtgeborenen\".", progress = "Ich brauche ein Exemplar von \"Nächte mit den Nachtgeborenen\", damit wir unsere Bemühungen vertiefen können. Vermutlich habe ich es nach dem Flug hierher liegen lassen.", completion = "Ah, danke, dass Ihr das gefunden habt. Lasst mich mal sehen, wir wollen uns ja die Stilvollsten der Nachtgeborenen vornehmen... Die Liste scheint mir perfekt zu sein... Oh, die sieht ja gefährlich aus... und der auch... nun gut.\n\nEs gibt viel zu tun. Ihr solltet besser anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46679] = { id = 46679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenfaden", description = "Vandros von den Nachtgeborenen: Das ist ein Elf, der sich zu kleiden weiß. Schon als junger Adliger am Hofe von Farondis war Vandros für seine schneidigen und modisch innovativen Outfits bekannt.\n\nIch habe seine Kleidung nie von Nahem sehen können, aber meine Nachforschungen haben ergeben, dass das Geheimnis seiner Schneidertechnik weniger auf dem Stoff als vielmehr auf dem Faden beruht. Er scheint aus den Schatten selbst zu bestehen.\n\nIhr wisst sicher, wie Ihr da rankommt. Beschafft seine Roben und entnehmt ihnen den Faden.", sourceObjective = "Bezwingt Berater Vandros im Arkus auf dem Schwierigkeitsgrad 'Mythisch' und extrahiert Schattenfaden aus seinen Roben.", progress = "Vandros zu bezwingen, mag eine Herausforderung darstellen, doch wir brauchen wirklich Schattenfaden von seinen Roben.", completion = "Ausgezeichnet, {name}! Oh, was für prächtige Dinge Ihr damit nähen könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[46680] = { id = 46680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sternenlichtfaden", description = "Melandrus von den Nachtgeborenen ist die Erste Klinge der Elisande. Vielleicht habt Ihr schon von ihm gehört? Er ist ein großer Held der Nachtgeborenen, aber, um ehrlich zu sein, seiner Kleidung fehlt es fast gänzlich an Stil.\n\nSeine Accessoires machen sich dagegen etwas besser, vor allem ein bestimmtes Paar Armschienen. Der für diese Schienen verwendete Faden wäre sogar perfekt für Eure nächsten Outfits. Wenn Ihr ihn besorgt habt, können wir ja alles Weitere besprechen.", sourceObjective = "Bezwingt Berater Melandrus im Hof der Sterne und extrahiert Sternenlichtfaden aus seinen Armschienen.", progress = "Habt Ihr den Faden aus Melandrus' sternengestreiften Armschienen extrahieren können?", completion = "Ausgezeichnete Arbeit, mein Freund! Ich werde so bald wie möglich gute Verwendung dafür finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[46681] = { id = 46681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenfaden", description = "Habt Ihr schon mal Elisande, die Großmagistrix der Nachtgeborenen, bewundern können? Atemberaubend! Stilsicher! Perfekte Haltung!\n\nVon Ihr könnt Ihr Euch eine Scheibe abschneiden! Oder vielmehr solltet Ihr der Großmagistrix ihre Seelenwickeltücher der Suramari abschneiden, um den Faden zu entnehmen! Die Tücher sind von hohem symbolischem Wert und sie wird sie mit ihrem Leben verteidigen.\n\nAlso zieht los, bezwingt sie und holt Euch den Faden.", sourceObjective = "Bezwingt Großmagistrix Elisande in der Nachtfestung und extrahiert Seelenfaden aus ihren Wickeltüchern.", progress = "Großmagistrix Elisandes Seelenwickel haben den schönsten Faden! Das soll Euch jetzt keinen Druck machen, aber... ich warte.", completion = "Dieser Seelenfaden ist wirklich wundervoll! Ich bin sehr angetan, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[46682] = { id = 46682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder der Ahnen", description = "{name}, wir müssen Stoff von höchster Qualität verarbeiten. Glücklicherweise sind die Webwaren der uralten Nachtgeborenenschneider äußerst gut. Es mag in gewisser Hinsicht eine verlorene Kunst sein, doch ich denke, ich kann ihre Meisterwerke hernehmen und sogar noch mehr daraus machen.\n\nEinige unserer Feinde in dieser Gegend tragen noch uralte magieerfüllte Seidenrüstung. Entnehmt das Seidengewebe aus jedem Rüstungsteil, das Ihr hier an der Verheerten Küste entdeckt.", sourceObjective = "Beschafft 100 Stück uraltes magieerfülltes Seidengewebe von Humanoiden an der Verheerten Küste.", progress = "Haltet Ausschau nach uraltem magieerfülltem Seidengewebe. Wir brauchen eine Menge davon, um damit anzufangen, fantastische Dinge zu fertigen.", completion = "Ah, das ist genau das, was wir brauchen, junger {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46683] = { id = 46683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternengewebe und Schattenstoff", description = "Jetzt seid Ihr endlich bereit für die wahren Geheimnisse der Schneiderkunst. Ihr habt es Euch redlich verdient. \n\nDie von Euch gesammelten Materialien habe ich zu einem Bündel legendärer Schneidermaterialien zusammengeführt.\n\nGeht zum Webstuhl der anmutigen Königin und webt dort zwei Ballen Stoff. Nach meiner Forschung zu Mode, Helden und Legenden bin ich der Ansicht, dass dieser neue Stoff von unvergänglicher Bedeutung sein wird. Und jetzt los!", sourceObjective = "Stellt einen Sternengewebeballen und einen Schattenstoffballen her.", progress = "Bitte stellt so schnell wie möglich einen Sternengewebeballen und einen Schattenstoffballen am Webstuhl her und bringt sie zu mir, damit ich sie abschließend prüfen kann.", completion = "So etwas wie den von Euch erschaffenen Stoff habe ich noch nie erblickt. Wunderschön!\n\nNehmt diese Stücke und macht etwas Wunderbares daraus. Ich werde als Erster über Eure Erfolge schreiben und glaube wahrlich, dass Ihr endlich zum Symbol von heldenhaftem Stil geworden seid, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46684] = { id = 46684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende vom Urbalg", description = "Die Lederverarbeitung zählt zu den ältesten Handwerksformen dieser Welt. Tierhäute waren die ersten Kleidungsstücke. Die Legenden berichten von einer besonderen Lederverarbeitung, die in unseren modernen Zeiten kaum noch bekannt ist.\n\nDurch die Kombination der Magie der Erde mit einigen der feinsten Ledersorten aller Zeiten und unter Zuhilfenahme sorgfältigster Analyse sowie meines Verständnisses von Stil konnte meine Wenigkeit diese Technik wiederaufleben lassen.\n\nZunächst müsst Ihr ein paar uralte Irrwische fangen, um die richtige Naturmagie für den Bearbeitungsvorgang kanalisieren zu können.", sourceObjective = "Fangt uralte Irrwische in Val'sharah ein.", completion = "Uralte Irrwische? Das ist ja wundervoll! Ein guter Anfang, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[46685] = { id = 46685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Irrwisch und der Schatten", description = "{name}, habt Ihr schon vom Alptraumfürsten Xavius gehört, dessen Schemen im Finsterherzdickicht herumspukt? Ich habe gehört, dass dieser Schemen manchmal einen farblosen Schleier trägt.\n\nDieser Schleier ist durchdrungen von mächtiger Magie und der Irrwisch wird sie für Euch zum Vorschein bringen.\n\nWenn es Euch gelingt, gegen den Schemen zu kämpfen, ihm den Schleier abzunehmen und diesen mit Euren Fertigkeiten zu färben, werde ich Euch zeigen, wie man Wunder bewirken kann!", sourceObjective = "Bezwingt den Schemen von Xavius im Finsterherzdickicht auf dem Schwierigkeitsgrad 'Mythisch' und färbt seinen Schleier.", progress = "Habt Ihr den Schleier schon erbeutet und gefärbt? Begebt Euch ins Finsterherzdickicht und erledigt das.", completion = "Der Schleier ist perfekt, {name}. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[46686] = { id = 46686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Irrwisch und das Meer", description = "Königin Azshara und ihre Hofdamen sind Gegenstand vieler tragischer Geschichten. Ihre Macht und ihre Überheblichkeit brachten sie vom rechten Weg ab, aber dennoch blieben ihre Hofdamen ihr bis heute treu ergeben. Darin liegt eine gewisse Macht.\n\nAzsharas Zorn ist zwar eine Abscheulichkeit, aber in Wahrheit handelt es sich um eine ihrer Hofdamen, die bereitwillig ihr Leben gab, um ihre Königin zu schützen. Nur wenige wissen das. Der uralte Irrwisch kennt diese Wahrheit, und wenn Ihr ihn mit in den Kampf gegen Azsharas Zorn nehmt, könnt Ihr vielleicht die Handschuhe der Hofdame finden. Setzt sie wieder instand.", sourceObjective = "Beschafft die durchnässten Handschuhe der Hofdame von Azsharas Zorn auf dem Schwierigkeitsgrad 'Mythisch' und behandelt sie dann.", progress = "Ihr müsst gegen Azsharas Zorn kämpfen, um ein Paar Handschuhe der Hofdame zu finden und wiederherzustellen.", completion = "Diese Handschuhe vermitteln eine gewisse Traurigkeit, findet Ihr nicht auch? Wie auch immer, danke, dass Ihr sie wiederhergestellt und hierhergebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46687] = { id = 46687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Irrwisch und der Alptraum", description = "Xavius, der Alptraumfürst in Val'sharah, bezieht einen Teil seiner Macht aus seiner Zauberschärpe. Sie ist magisch an die Welt unter seinen Füßen gebunden und lässt sich nicht von seinem Körper lösen.\n\nSollte es Euch allerdings gelingen, Xavius im Kampf zu besiegen, kann die Zauberschärpe mithilfe des uralten Irrwischs entfernt werden. Für jemanden von Euren Fähigkeiten dürfte das ein Kinderspiel sein, da bin ich sicher.\n\nNehmt den Irrwisch mit zum Smaragdgrünen Alptraum, bringt die Zauberschärpe an Euch und setzt Eure Fähigkeiten ein, um alle Schäden zu reparieren, die Ihr im Kampf möglicherweise verursacht habt.", sourceObjective = "Beschafft die Zauberschärpe von Xavius im Smaragdgrünen Alptraum und repariert sie.", progress = "{name}, besiegt Xavius und holt mir seine Zauberschärpe. Stellt sicher, dass sie repariert und wieder in einwandfreiem Zustand versetzt wurde!", completion = "Die Zauberschärpe sieht perfekt aus, {name}! Ich hätte sie selbst nicht besser reparieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[46688] = { id = 46688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leder der Ahnen", description = "{name}, wir werden qualitativ hochwertiges Leder für unsere Arbeit brauchen. Uraltes Schreckensleder ist in dieser Gegend das beste Material, und die hiesigen Gerbtechniken haben sich als überragend erwiesen. Für das ungeübte Auge mag es so aussehen wie gewöhnliches Schreckensleder. Und da kommt der Irrwisch ins Spiel.\n\nViele unserer Feinde an der Verheerten Küste tragen sicher etwas Uraltes Schreckensleder bei sich. Wenn Ihr sie besiegt, werdet Ihr Rüstungsteile erkennen, die aus diesem Material gefertigt sind, und dann könnt Ihr das Leder für unsere Zwecke entnehmen.", sourceObjective = "Beschafft 100 Stück uraltes Schreckensleder von Humanoiden an der Verheerten Küste.", progress = "Haltet Ausschau nach uraltem Schreckensleder. Wir werden eine Menge davon für unsere Zwecke brauchen.", completion = "Hierbei handelt es sich tatsächlich um Schreckensleder. Das sollte für unsere Zwecke ausreichen, {name}. Habt vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[46689] = { id = 46689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrwischberührter Urbalg", description = "Schreckensleder kann mit Wissen, das mit großer Sorgfalt aus uralten Texten gewonnen wurde, in Urbalg umgearbeitet werden. Zum Teil gehört dazu fortgeschrittene Handwerkskunst, zum Teil einfache Erdmagie.\n\nAus den uralten Irrwischen, die Ihr eingefangen habt, den Materialien, die Ihr erbeutet habt, und meinen Forschungsergebnissen habe ich ein legendäres Kürschnerset für Euch zusammengestellt. Geht damit zu den ererbten Bälgen von Hrul Scharfzahn in Donnertotem. Der Irrwisch wird Euch dort bei der Benutzung des Sets helfen, um Urbalg herzustellen.", sourceObjective = "Benutzt das legendäre Kürschnerset in Hrul Scharfzahns Behausung in Donnertotem.", progress = "Hrul Scharfzahn hat Bälge in seiner Behausung in Donnertotem. Wenn Ihr Euch ihnen nähert, könnt Ihr Euer Set benutzen. Bringt mir dann das Ergebnis zur abschließenden Prüfung.", completion = "Der von Euch erschaffene Urbalg ist großartig. Nehmt ihn und zaubert daraus etwas Wunderschönes und Einzigartiges.\n\nDas stellt eine herausragende Leistung dar und Ihr werdet garantiert umwerfend aussehen. Darin kenne ich mich immerhin aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[46690] = { id = 46690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende der Wächterschuppen", description = "Eine meiner Lieblingslegenden ist die des Eulenvaters auf der Insel der Behüter. Man sagt, dass sein Geist in schweren Zeiten kommt, um seinen Kreaturen Mut zuzusprechen.\n\nSeit der Ankunft der Legion auf der Insel der Behüter wurden viele Eulen getötet, also werdet Ihr ihn dort finden.\n\nWir müssen ihn uns für eine kurze Zeit \"ausleihen\", da er Zeuge vieler Schlachten war, in denen berühmte Krieger und Bösewichte Rüstungen aus Wächterschuppen trugen. Mit seinem Geist könnt Ihr Gegenstände identifizieren, aus denen wir die Schuppenteile entnehmen können, um sie dann für unsere Kreationen zu verwenden!", sourceObjective = "Fangt den Eulenvater auf der Insel der Behüter ein.", progress = "Habt Ihr den Eulenvater schon eingefangen?", completion = "Welch großartige Kreatur! Erlaubt mir, ihn auf Euch einzustimmen... So! Mit diesem uralten Wissen sind wir jetzt bereit, zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46691] = { id = 46691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eule und der Verräter", description = "Ich habe die Geschichten und Legenden nach Rüstungen durchforstet, in denen Wächterschuppen verarbeitet wurden, und Cordana Teufelsang ist ein Name, der meine Aufmerksamkeit erregt hat.\n\nSie besitzt nachweislich einen Familienmantel, der das von uns Benötigte enthält. Tötet sie und nehmt dem Leichnam dieser Verräterin den Mantel ab. Die Eule wird dafür sorgen, dass Ihr ihn entdeckt.\n\nWahrscheinlich ist er durch jahrelanges Tragen abgewetzt, also versetzt ihn wieder in einwandfreien Zustand und bringt ihn mir.", sourceObjective = "Findet und repariert Cordana Teufelsangs Mantel im Verlies der Wächterinnen auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Habt Ihr Cordanas Mantel schon gefunden und wiederhergestellt? Gerüchten zufolge soll sie sich im Verlies der Wächterinnen aufhalten.", completion = "Der Mantel sieht nagelneu aus! Ausgezeichnete Handwerkskunst, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46692] = { id = 46692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eule und der Schreckenslord", description = "Der Dämon Mephistroth ist einer der mächtigsten unter den Nathrezim - den Schreckenslords. Ich sehe in Euren Augen, dass Ihr wisst, was ich von Euch verlangen werde. Aber es ist nur zu Eurem Besten! So, wie Ihr ausseht, könnt Ihr nicht länger durch die Lande streifen.\n\nVor Kurzem wurde Mephistroth von der Legion zur Kathedrale der Ewigen Nacht entsandt. Zweifellos wird er Beinplatten tragen und ich glaube, dass diese Wächterschuppen enthalten. Nehmt sie an Euch, poliert sie auf und bringt sie mir.", sourceObjective = "Findet und restauriert Mephistroths Beinplatten, indem Ihr ihn in der Kathedrale der Ewigen Nacht auf dem Schwierigkeitsgrad 'Mythisch' besiegt.", progress = "Habt Ihr Mephistroth besiegt und seine Beinplatten aufpoliert?", completion = "Diese Beinplatten sind ziemlich groß! Ich bin überrascht, dass Ihr die Begegnung überlebt habt... und dass Ihr sie so wunderbar aufgearbeitet habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[46693] = { id = 46693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eule und der Beobachter", description = "Ich habe schon einige widerwärtige Kreaturen im Laufe meines Lebens erforscht, aber Viz'aduum der Beobachter steht ganz weit oben auf der Liste. Ich meine, er ist ein riesiger, ekliger, gefährlicher Augapfel!\n\nIm Moment treibt er in Karazhan sein Unwesen... Ihr habt davon gehört? Zu Zeiten Medivhs wurde ein großer Teil unseres gesamten Wissens dort aufbewahrt. Leider liegen diese Zeiten hinter uns...\n\nIch schweife ab. Viz'aduum der Beobachter besitzt Rüstung aus dem Ersten Krieg - tatsächlich handelt es sich um Armschienen - und sie sind unglaublich wertvoll. Ich sage es nur ungern, aber nehmt sie an Euch, repariert sie und dann müssen wir ihre Wächterschuppen benutzen.", sourceObjective = "Tötet Viz'aduum im Dungeon Rückkehr nach Karazhan auf dem Schwierigkeitsgrad 'Mythisch', nehmt die zerrissenen Armschienen des Ersten Krieges an Euch und repariert sie.", progress = "Habt Ihr diese furchtbare Bestie besiegt und mir die Armschienen des Ersten Krieges mitgebracht?", completion = "Um diese Armschienen ranken sich ganz eigene Legenden. Nur schade, dass wir sie opfern müssen, um Euch zu einem anständigen Ruf zu verhelfen, aber wir müssen alle für die Mode leiden.\n\nIch würde Euch auch gern persönlich dafür danken, dass Ihr Viz'aduum getötet habt. So etwas sollte einfach nicht... existieren. Ich meine... Ach, Ihr wisst, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[46694] = { id = 46694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kettenrüstung der Ahnen", description = "Hier und da auf den Verheerten Inseln lassen sich Wächterschuppen finden. Verschiedene Gegner und hiesige Monster, die versuchen, die überlegenen Völker wie uns nachzuäffen, haben sie aufgesammelt und getragen.\n\nDie Art, die wir benötigen, die uralte Gravurschuppe, gehört zu den ältesten überhaupt. Sammelt, so viel Ihr davon finden könnt, und bringt sie mir. Wir werden das, was davon noch brauchbar ist, aus ihnen herausholen.", sourceObjective = "Beschafft 100 Stück uralte Gravurschuppe von Humanoiden an der Verheerten Küste.", progress = "Habt Ihr die uralten Gravurschuppen, die wir brauchen?", completion = "Da sollten genug uralte Gravurschuppen sein. Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46695] = { id = 46695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassige Wächterschuppen", description = "Ich glaube, es ist endlich an der Zeit, dass Ihr etwas wahrhaft Bemerkenswertes erschafft. Für eine Rüstung, mit der Ihr Euch von den anderen abhebt, müssen wir die besten Wächterschuppen herstellen.\n\nFindet die Nachtelfe Celea in Azsuna. Sie hat den Boden um sich herum geweiht und eingestimmt, um die Magie unserer Welt zu fokussieren. Nur dort könnt Ihr erschaffen, was wir brauchen. Beeilt Euch, {name}.", sourceObjective = "Findet Celea in Azsuna und erschafft die Wächterschuppen, wo die Magien zusammenlaufen.", progress = "Habt Ihr Celea in Azsuna gefunden und die Wächterschuppen neben ihr hergestellt? Es wird nur an genau dieser Stelle funktionieren. Bringt sie zu mir zurück, wenn Ihr das erledigt habt.", completion = "Die Wächterschuppen sind unglaublich leicht und doch so stark. Ich habe noch nie etwas Vergleichbares gesehen. {name}, mehr kann ich nicht tun. Es liegt jetzt ganz an Euch.\n\nNehmt, was Ihr errungen habt, und wirkt Wunder damit. Wunder der Stilsicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[46696] = { id = 46696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende der vier Hämmer", description = "{name}, wir sollten ehrlich miteinander sein, bevor wir anfangen. Ihr seid <gelernter Schmied/gelernte Schmiedin> und das ist ein ehrenhafter Beruf. Doch ich schätze Stil und Mode. Schwere Rüstung und Waffen verleihen dem Profil eines Helden eine gewisse Massigkeit und ich finde, das macht diese Art von Kleidung eher unelegant.\n\nAber keine Angst, ich kann Euch immerhin etwas lehren, das Euch auf den Geschmack für feinere Materialien bringen wird.\n\nGeht nach Dalaran und findet ein Buch über drei vergessene Helden, das von meinem Bruder übersetzt wurde. Wir werden die feinsten Metalle finden, die jemals geschmiedet wurden!", sourceObjective = "Geht nach Dalaran und findet die Legende der vier Hämmer.", progress = "Habt Ihr den verstaubten alten Folianten von Fafnir gefunden? Ich muss zugeben, dass er darin möglicherweise etwas Interessantes entdeckt haben könnte.", completion = "Ah, das Buch! Lasst mal sehen... bla bla bla drei Helden... bla bla bla drei Hämmer schmieden und daraus den ultimativen Hammer herstellen... bla bla bla, Schmied wird durch unmögliche Erwartungen sprichwörtlich niedergeschmettert und möglicherweise wortwörtlich getötet et cetera pp. Sieht gut aus!\n\nEs scheint, ich kann Euch helfen, die Überreste der Rüstung und Waffen dieser Helden zu finden, und diese unglaublichen Materialien können dann dazu benutzt werden, um erstaunliche Dinge herzustellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[46697] = { id = 46697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gottesstreiter", description = "Der Gottesstreiter kämpfte als Champion auf Seiten der Sterblichen gegen das, was er als Unterdrückung und Missbrauch durch unsterbliche Wesen betrachtete. Die Legenden besagen, dass die Götter ihn fürchteten, doch schließlich fiel er.\n\nMeine Nachforschungen haben ergeben, dass die Götter, die er bekämpfte, die Götter Sturmheims waren. Insbesondere Odyn. Der Schild des Gottesstreiters erlitt so viel Schaden durch Blitzschläge, dass er zu Blitzstahl wurde. Nachdem der Gottesstreiter starb, nahm Odyn den Schild als Trophäe an sich und schmolz ihn ein. Holt diesen Blitzstahl von ihm und schmiedet daraus einen Hammer.", sourceObjective = "Holt den weißen Blitzstahl von Odyn in den Hallen der Tapferkeit auf dem Schwierigkeitsgrad 'Mythisch' und schmiedet daraus einen Hammer.", progress = "Habt Ihr den weißen Blitzstahl von Odyn geholt und ihn zu einem Hammer verarbeitet?", completion = "Was für ein bemerkenswertes Metall! Ich spüre ein Kribbeln, wenn ich es nur in den Händen halte. Unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[46698] = { id = 46698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenjägerin", description = "Die Drachenjägerin lebte in einer Zeit vor der Geschichtsschreibung und ihre Geschichte wurde uns mündlich überliefert.\n\nAnscheinend quälten die Drachen ihr Volk, und nachdem ihr Dorftempel vernichtet worden war, rief sie die einheimischen Stämme zusammen, wurde ihre Königin und tötete alle Drachen. Dann wurde sie aus irgendeinem Grund verbannt und zog bis zu ihrem Tod einsam umher. Beweis für diese Geschichte ist ein Stück drakonische Schlacke, das von einem Metallgötzen in ihrem Geburtsort übrig geblieben war. Dargul der Unterkönig hat es jetzt. Schmiedet einen Hammer daraus.", sourceObjective = "Besiegt Dargul in Neltharions Hort auf dem Schwierigkeitsgrad 'Mythisch' und fertigt einen Hammer aus Darguls glühend heißer drakonischer Schlacke.", progress = "Habt Ihr die drakonische Schlacke aus dem Dorftempel des Geburtsorts der Drachenjägerin gefunden? Wenn ja, dann schmiedet daraus einen Hammer.", completion = "Eine mächtige Magie hat dafür gesorgt, dass die drakonische Schlacke auch nach so vielen Jahren noch so heiß ist. Vielleicht handelt es sich um den Willen der Drachenjägerin? War Drachenfeuer in den alten Zeiten sogar noch gefährlicher? Oder hat sie damals sogar keinen Geringeren als den Drachen Neltharion bekämpft, den Ihr als Todesschwinge kennt?\n\nIch frage mich, ob wir das je herausbekommen werden.\n\nGut gemacht! Der Hammer ist außergewöhnlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[46699] = { id = 46699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höllenschlächterin", description = "Die Geschichte der Höllenschlächterin ist eine klassische Rachegeschichte. Odyn wollte die Seelen der Tapfersten als seine Champions haben, aber Helya schickte ihre Kvaldir los, um diese Seelen als Erste zu bekommen. Die Bewohner von Sturmheim waren nicht mehr als ihre Schachfiguren und litten darunter.\n\nDie Kvaldir kamen mitten in der Nacht zum Schiff der Höllenschlächterin, töteten ihren Sohn und nahmen seine Seele, die Helya für alle Ewigkeit dienen sollte. Die Höllenschlächterin nahm ihre Axt und den Speer ihres Sohns an sich und schickte sich an, Rache zu nehmen. Beendet ihre Mission. Tötet Helya und schmiedet einen Hammer aus dem frostgeaderten Schiefer.", sourceObjective = "Besiegt Helya und schmiedet einen Hammer aus dem frostgeaderten Schiefer in der Prüfung der Tapferkeit.", progress = "Der frostgeaderte Schiefer ist das, was von den Waffen der Höllenschlächterin übrig geblieben ist, nachdem sie auf Helyas kalter Schmiede vernichtet wurden. Es ist mächtiges Zeug und wir brauchen es.", completion = "Der Hammer ist perfekt, aber ziemlich kalt. Ich respektiere Eure Handwerkskunst!", sourceObjectiveStatus = "unverified-source-field" }
quests[46700] = { id = 46700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung der Ahnen", description = "Wir benötigen nicht nur die Hämmer und meine sorgfältigen Nachforschungen, {name}. Wir brauchen außerdem eine Menge uraltes Metall von bester Qualität, um den letzten Hammer herzustellen.\n\nGegner an der Verheerten Küste, die Rüstungen tragen können, führen gelegentlich Teile uralten Dämonenstahls mit sich. Sammelt während Eurer Kämpfe genug davon für unsere Zwecke.", sourceObjective = "Beschafft 100 Stück uralten Dämonenstahl von Humanoiden an der Verheerten Küste.", progress = "Habt Ihr den uralten Dämonenstahl, den wir benötigen?", completion = "Das wird für unsere Zwecke reichen. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46701] = { id = 46701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer der vergessenen Helden", description = "{name}, ich muss zugeben, das hier ist aufregend. Ich habe alles, was Ihr gesammelt habt, in diese Kiste mit Vorräten gelegt, und der einzige Ort mit genug Macht und Magie, um die Herstellung des letzten Hammers zu bewältigen, ist der Firmamentstein. Ich gehe davon aus, dass Schmiede mit Euren anspruchsvollen Fertigkeiten ihn kennen?\n\nMir ist klar, dass es da draußen gewisse Zwergenklischees gibt, was das Schmieden angeht, aber mir persönlich ist dieses Hämmern und die Hitze zuwider. Ich denke, deshalb habe ich den Pfad eines Gelehrten gewählt. Ich wünsche Euch viel Glück!", sourceObjective = "Geht zum Firmamentstein am Hochberg und schmiedet den Hammer der vergessenen Helden.", progress = "Ihr müsst die Kiste mit Vorräten zum Firmamentstein bringen und den letzten Hammer schmieden. Bringt ihn mir dann zur abschließenden Prüfung.", completion = "Der Hammer ist wahrscheinlich der perfekteste Gegenstand, den Ihr je geschmiedet habt. Mit ihm könnt Ihr prachtvolle und stilsichere Rüstung herstellen und so zu einer echten Legende werden.\n\nIch bin stolz auf Euch, {name}. Ich bin so glücklich, dass Ihr endlich anfangen werdet, gut auszusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46705] = { id = 46705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenschlag", description = "Natürlich werde ich Euch helfen! Aber um ganz ehrlich zu sein, ich bin nicht ganz sicher, wo man heutzutage noch einen neuen arkanen Schildgenerator finden könnte. So viele Anhänger unseres Handwerks wurden hingerichtet... Ich werde darüber nachdenken.\n\nWürdet Ihr auch mir helfen? Ich beobachte seit einer Weile eine Gruppe Teufelsgeborener in der Nähe. Ihre Aktivitäten werden immer unverfrorener.\n\nIch denke, sie sollten lernen, wie es ist, gewaltsam unterdrückt zu werden.", sourceObjective = "Tötet 7 teufelsgeborene Aufrührer.", completion = "Rache ist so süß. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46707] = { id = 46707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener! Tötet auch den da!" }
quests[46709] = { id = 46709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready for Crafted Legendary" }
quests[46717] = { id = 46717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[46719] = { id = 46719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amal'thazads Botschaft", description = "<Todesgebieter/Todesgebieterin>, Amal'thazad hat Eure Anwesenheit in Acherus erbeten.\n\nEr stand in Kontakt mit dem Lichkönig und hat Verbesserungen an der Zitadelle vorgenommen.\n\nOb diese zu seinem oder Eurem Vorteil sind, weiß ich nicht.", sourceObjective = "Sprecht mit Amal'thazad in Acherus.", completion = "Ah, Todesgebieter, Ihr seid zurückgekehrt.\n\nIch habe einige gefrorene Runen oberhalb von Acherus platziert. Sobald sie abgestimmt sind, werdet Ihr... umfassender mit dem Lichkönig kommunizieren können.\n\nEr wird Euch Dinge zeigen können, die er Euch bisher nicht zeigen konnte.\n\n<Amal'thazad stößt ein furchtbares, krächzendes Geräusch aus, von dem Ihr nur annehmen könnt, dass es sich um ein Kichern handelt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[46720] = { id = 46720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefrorene Erinnerungen", description = "Schließt Eure Augen, <Todesgebieter/Todesgebieterin>. Könnt Ihr seine Präsenz nicht bereits spüren?\n\n<Die eisige Präsenz des Lichkönigs macht sich augenblicklich in Eurem Geist bemerkbar.>\n\nStellt Euch in den Runenkreis an der Spitze von Acherus, <Todesgebieter/Todesgebieterin>.\n\nIch werde Euch zeigen, was ich gesehen habe.\n\n<Die Präsenz schwindet.>", sourceObjective = "Nehmt das Portal zum oberen Bereich von Acherus, hört Euch den Plan des Lichkönigs an und werdet Zeuge seiner Vision in Eiskrone.", sourceObjectiveStatus = "unverified-source-field" }
quests[46721] = { id = 46721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sulfuron Hammer" }
quests[46722] = { id = 46722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts in meinem Ärmel", description = "Also, Ihr mögt ja glauben, dass ein Säckchen voller Gold eine gute Belohnung für Eure Mühen ist, aber ich denke da an noch etwas Besseres für Euch.\n\nIch werde Euch mein bestes Kunststück beibringen!\n\nIch weiß, ich weiß, ich bin ein sehr großzügiger Goblin. Lasst mich Euch zeigen, wie man es richtig macht.", sourceObjective = "Benutzt Akazamzaraks Hut, um ein magisches Kunststück durchzuführen.", progress = "Werdet Ihr das Kunststück nun vollführen oder nicht?", completion = "Das ist eine Katastrophe! Etwas stimmt mit meiner Kaninchendimension nicht!\n\nAlso schön, ich werde noch einmal Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46723] = { id = 46723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinunter in den Kaninchenbau", description = "Also schön. Ihr müsst für mich dort hineingehen und herausfinden, was schiefläuft. Ich würde das ja selbst machen, aber... naja, es ist kompliziert.\n\nAuf jeden Fall haben wir keine Zeit zu verlieren! Springt einfach nur in den Hut und findet heraus, was los ist.\n\nIch halte mich bereit, um Euch herauszuziehen, sobald Ihr alles im Griff habt.", sourceObjective = "Begebt Euch in Akazamzaraks Hut hinein und findet heraus, was mit seinen Kaninchen passiert.", progress = "Nun steht nicht einfach nur da, ab in den Hut mit Euch! Helft den armen Hoppelhasis!", completion = "Ich kann nicht glauben, dass ein Wolf in meine Taschendimension gelangt ist! Das ist das letzte Mal, dass ich eine Kiste Kaninchen aus Mondbruch bestelle!\n\nIch schulde Euch was, Sportsfreund. Hier, nehmt meinen Ersatzhut. Aber macht mir bloß keine Konkurrenz in Dalaran, verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[46724] = { id = 46724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Der Große Akazamzarak", description = "Wisst Ihr, es ist ziemlich nützlich, Euch in der Nähe zu haben, {name}.\n\nIch sag Euch was: Ich glaube, ich werde Euch bei Euren Abenteuern begleiten. Man scheint dabei eine Menge Gold verdienen zu können und ich glaube, es wäre ein guter Weg, um sich nach ein paar neuen Geschäftsgelegenheiten auf den Verheerten Inseln umzusehen.\n\nWas meint Ihr?Ihr erlernt:", sourceObjective = "Wisst Ihr, es ist ziemlich nützlich, Euch in der Nähe zu haben, {name}.\n\nIch sag Euch was: Ich glaube, ich werde Euch bei Euren Abenteuern begleiten. Man scheint dabei eine Menge Gold verdienen zu können und ich glaube, es wäre ein guter Weg, um sich nach ein paar neuen Geschäftsgelegenheiten auf den Verheerten Inseln umzusehen.\n\nWas meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[46725] = { id = 46725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Saft abgedreht", description = "Kor'vass bat noch um ein paar andere Dinge, aber ess würde ihr nicht schaden, ein wenig Geduld zu lernen. Meint Ihr nicht auch?\n\nSie erwähnte, dasss dass Waffenarsenal dess Schiffs schwer beschädigt isst und nur noch über gefährlich wenig Energie verfügt. Aber so, wie ich sie kenne, übertreibt sie bestimmt mal wieder.\n\nIch denke, Ihr könntet diesen Energiekern, den ich konfissziert habe, mitnehmen. Ihr könnt ihn an den widerlichen Legionssgeysiren und Energiekugeln wiederaufladen, die am Grabmal herumschweben.", sourceObjective = "Füllt den Energiekern der Teufelshammer mit Teufelsenergie auf.", completion = "Ich hatte schon immer Höhenangsst. Ich bin froh, dasss Ihr derjenige seid, der die Schmutzarbeit erledigen musss.", sourceObjectiveStatus = "unverified-source-field" }
quests[46727] = { id = 46727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Gezeiten des Krieges", description = "Champion!\n\nEs wurde ein dringender Kriegsrat einberufen. Ihr werdet in Burg Sturmwind erwartet.", sourceObjective = "Nehmt am Kriegsrat in Burg Sturmwind teil.", progress = "Ich danke Euch für Euer Kommen.", completion = "Die Horde hat uns erneut zum Handeln gezwungen.\n\nDas können wir nicht tolerieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[46728] = { id = 46728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nation Kul Tiras", description = "Kul Tiras besitzt die größte Seestreitmacht von Azeroth und ist ein früherer Verbündeter. Aber leider haben wir kaum noch Kontakt zu ihnen, seit Jainas Vater, Lordadmiral Daelin Prachtmeer, in Theramore besiegt wurde.\n\nViele haben Jainas Entscheidung damals verurteilt und meinten, sie wäre von der Aussicht auf einen Frieden zwischen Allianz und Horde so überzeugt gewesen, dass sie ihren eigenen Vater verraten hat.\n\nVielleicht spürt sie jetzt, dass die Zeit gekommen ist, Wiedergutmachung zu leisten.\n\nSo sehr ich die Vorstellung hasse, Jaina einer Gefahr auszusetzen... Kul Tiras muss sich der Allianz anschließen.\n\nViel Glück.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer im Hafen von Sturmwind.", completion = "Nach all der Zeit wieder zu Hause.", sourceObjectiveStatus = "unverified-source-field" }
quests[46729] = { id = 46729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Ritter", description = "Mittlerweile ist Carsten der Hafenmeister, doch früher war er einer von Daelin Prachtmeers angesehensten Rittern!\n\nIch habe meine Mutter verloren, als die Geißel Lordaeron heimsuchte. Mein Vater schickte mich hierher, in die vermeintliche Sicherheit vor dem Krieg. Ich weiß nicht viel über ihn. Nur, dass er ein Ritter von Sturmwind war und sein Leben im Kampf gegen den Lichkönig gelassen hat.\n\nDaelin hat Carsten höchstpersönlich ausgewählt, um mich aufzuziehen, und ihn somit gezwungen, einen Schreibtischjob anzunehmen. Das ist der einzige Grund, warum er nicht in Theramore war.\n\nEr schaut wahrscheinlich auf dem anderen Allianzschiff vorbei. Gehen wir!", sourceObjective = "Trefft Euch mit Carsten Jammerthal.", progress = "Tut mir leid, ich hätte Euch darauf hinweisen sollen, dass er sich manchmal... nicht gerade kurz fasst.", completion = "Ich habe Carsten noch nie so aufgedreht gesehen!\n\nKlingt, als hätten wir Arbeit zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46730] = { id = 46730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legionsrichter", description = "Unter Eurer Führung ist unser Orden mächtiger geworden, als ich je zu hoffen gewagt hatte. Gemeinsam mit den Champions der anderen Orden haben wir jetzt eine Streitmacht, die die Brennende Legion aus unserer Welt vertreiben kann.\n\nZeit, dieser Invasion ein Ende zu setzen! Wir werden die Säulen der Schöpfung nutzen, um den Teufelssturm aufzulösen und das Grabmal des Sargeras zu versiegeln.", sourceObjective = "Begleitet Erzmagier Khadgar an Krasus' Landeplatz in Dalaran.", completion = "Unsere Streitkräfte sind versammelt. Wir sind bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[46732] = { id = 46732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schachzug des Propheten", description = "Ich spüre ihre Gegenwart gleich da vorn. Es ist nur ein ganz leiser Hauch von Wahrnehmung, aber ich kann mit Sicherheit sagen, dass es sich nicht um die Legion handelt.\n\nWir müssen herausfinden, ob diese Zerschlagenen potenzielle Verbündete sind. Es ist ein großes Risiko, aber unsere Ränge sind so dünn, dass wir diese Chance nutzen müssen.", sourceObjective = "Folgt Prophet Velen.", completion = "Turalyon lebt! Vielleicht gibt es doch noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[46733] = { id = 46733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Expansion Started Tracking Quest" }
quests[46734] = { id = 46734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Verheerte Küste", description = "Das hier war ein langer und verlustreicher Krieg, {name}. Zeit, ihn zu Ende zu bringen.\n\nWir werden die Brennende Legion aus ihrem Machtzentrum vertreiben und ihr Portal nach Azeroth schließen. Als Erstes müssen wir eine Position an der Verheerten Küste sichern.\n\nAls Gegner waren Allianz und Horde dem Untergang geweiht. Doch als Legionsrichter vereint werden wir siegreich sein!", sourceObjective = "Schließt das Szenario \"Angriff auf die Verheerte Küste\" ab.", completion = "Mephistroth ist auf der Flucht und wir haben eine Position hier an der Retterklippe gesichert.\n\nIch würde sagen, das ist ein guter Anfang, auch wenn wir noch viel vor uns haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[46735] = { id = 46735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beitrag zur Kommandozentrale" }
quests[46736] = { id = 46736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beitrag zum Netherdisruptor" }
quests[46743] = { id = 46743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Hochberg", description = "Champion, Eure Hilfe für unsere Leute hat unsere Erwartungen bei Weitem übertroffen und uns die dringend benötigte Zeit und Ruhe verschafft.\n\nBitte nehmt diese Vorräte für Euren Kampf gegen die Legion. Mit Eurer fortlaufenden Unterstützung sollten wir mehr davon sammeln und für Euch vorbereiten können.", sourceObjective = "Sprecht mit Ransa Graufeder am Hochberg, um Eure Belohnung zu erhalten.", completion = "Champion, Eure Hilfe für unsere Leute hat unsere Erwartungen bei Weitem übertroffen und uns die dringend benötigte Zeit und Ruhe verschafft.\n\nBitte nehmt diese Vorräte für Euren Kampf gegen die Legion. Mit Eurer fortlaufenden Unterstützung sollten wir mehr davon sammeln und für Euch vorbereiten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[46744] = { id = 46744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Macht gegen große Bedrohung", description = "{name}, der Krieg gegen die Legion ist wesentlich aufreibender geworden, als wir es uns vorgestellt hatten. Wir müssen dringend unsere Macht verstärken, damit wir dem Feind standhalten können.\n\nEs ist von höchster Dringlichkeit, dass Ihr Euer Artefakt so mächtig wie möglich macht. Nur so könnt Ihr der Bedrohung der Legion entgegenwirken.", sourceObjective = "Schaltet alle Boni einer Eurer Artefaktwaffen frei.", completion = "Ausgezeichnet! Euer Artefakt ist so mächtig wie möglich... zumindest für den Moment.\n\nWir arbeiten an einer zusätzlichen Lösung, aber in der Zwischenzeit solltet Ihr Euren Einsatz an der Verheerten Küste fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46745] = { id = 46745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Hof", description = "Prinz Farondis hat mich darum gebeten, Euch für Euren unermüdlichen Einsatz für unser Land zu danken.\n\nBitte nehmt diese Vorräte als Zeichen der Anerkennung. Zudem versprechen wir Euch mehr davon, wenn Ihr Eure Hilfe fortsetzt.", sourceObjective = "Sprecht mit Veridis Fallon in Azsuna, um Eure Belohnung zu erhalten.", completion = "Prinz Farondis hat mich darum gebeten, Euch für Euren unermüdlichen Einsatz für unser Land zu danken.\n\nBitte nehmt diese Vorräte als Zeichen der Anerkennung. Zudem versprechen wir Euch mehr davon, wenn Ihr Eure Hilfe fortsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46746] = { id = 46746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von den Valarjar", description = "Ich grüße Euch, <kleiner Held/kleine Heldin>.\n\nDer mächtige Odyn hat angeordnet, dass Ihr diese Kriegsbelohnungen erhalten sollt. Eure nimmermüde und mutige Hilfe für die Valarjar ist uns nicht verborgen geblieben.\n\nFür die Valarjar! Für Odyn! Für {name}!", sourceObjective = "Sprecht mit Valdemar Sturmsucher in Sturmheim, um Eure Belohnung zu erhalten.", completion = "Ich grüße Euch, kleiner Held.\n\nDer mächtige Odyn hat angeordnet, dass Ihr diese Kriegsbelohnungen erhalten sollt. Eure nimmermüde und mutige Hilfe für die Valarjar ist uns nicht verborgen geblieben.\n\nFür die Valarjar! Für Odyn! Für {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46747] = { id = 46747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte von den Traumwebern", description = "<Mein Held/Meine Heldin>!\n\nDank Eures Einsatzes bei der Verteidigung von Val'sharah konnten wir uns vorübergehend vom verderbenden Einfluss der Legion befreien und ein paar Vorräte sammeln, die wir Euch überlassen möchten.\n\nHier, bitte nehmt sie. Und Ihr sollt wissen, dass wir mehr solcher Belohnungen in Aussicht stellen, wenn Ihr uns weiterhin unterstützt.", sourceObjective = "Sprecht mit Sylvia Hirschhorn in Val'sharah, um Eure Belohnung zu erhalten.", completion = "Mein Held!\n\nDank Eures Einsatzes bei der Verteidigung von Val'sharah konnten wir uns vorübergehend vom verderbenden Einfluss der Legion befreien und ein paar Vorräte sammeln, die wir Euch überlassen möchten.\n\nHier, bitte nehmt sie. Und Ihr sollt wissen, dass wir mehr solcher Belohnungen in Aussicht stellen, wenn Ihr uns weiterhin unterstützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46748] = { id = 46748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Nachtsüchtigen", description = "Fremdling, ich habe ein paar Vorräte für Euch. Diese Waren sollen Euch gehören, weil Ihr unsere Truppen hier in Suramar pausenlos unterstützt habt.\n\nSolltet Ihr unseren Leuten weiterhin so unermüdlich helfen, verspreche ich Euch weitere Schätze.\n\nMein aufrichtigster Dank gehört Euch.", sourceObjective = "Sprecht mit der Ersten Arkanistin Thalyssra in Suramar, um Eure Belohnung zu erhalten.", completion = "Fremdling, ich habe ein paar Vorräte für Euch. Diese Waren sollen Euch gehören, weil Ihr unsere Truppen hier in Suramar pausenlos unterstützt habt.\n\nSolltet Ihr unseren Leuten weiterhin so unermüdlich helfen, verspreche ich Euch weitere Schätze.\n\nMein aufrichtigster Dank gehört Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46749] = { id = 46749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Wächterinnen", description = "Eure aufopferungsvolle Hilfe für uns hat Früchte getragen. Wir haben ein paar Vorräte für Euch.\n\nWenn Ihr nicht nachlasst, gibt es noch mehr davon.", sourceObjective = "Sprecht mit Marin Klingenflügel in Azsuna, um Eure Belohnung zu erhalten.", completion = "Eure aufopferungsvolle Hilfe für uns hat Früchte getragen. Wir haben ein paar Vorräte für Euch.\n\nWenn Ihr nicht nachlasst, gibt es noch mehr davon.", sourceObjectiveStatus = "unverified-source-field" }
