quests[46765] = { id = 46765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verheerte Küste: Untersuchung der Legion", description = "Wir konzentrieren uns zurzeit zwar auf die Verheerte Küste, aber wir müssen uns auch auf Bedrohungen an anderer Stelle gefasst machen. Wir haben verstörende Berichte darüber erhalten, dass die Legion indirekte Bedrohungen auf Azeroth anzettelt oder unterstützt.\n\nBitte haltet während Eures Aufenthalts an der Verheerten Küste Ausschau nach Informationen oder Objekten, die uns Hinweise über diese Bedrohungen liefern können.\n\nIch weiß, dass diese Angaben etwas vage sind, aber wir werden von hier aus ebenfalls unser Bestes tun.", sourceObjective = "Deckt während Eures Aufenthalts an der Verheerten Küste eine Legionsbedrohung auf.", progress = "Was gefunden?", completion = "Diese Schriftrolle ist... faszinierend. Sie zeigt, dass unsere Bedenken hinsichtlich indirekter Legionsbedrohungen berechtigt waren. Wir müssen zurück nach Dalaran, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[46766] = { id = 46766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulgthax" }
quests[46767] = { id = 46767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximillian 1 Week Cooldown" }
quests[46768] = { id = 46768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akazamzarak 1 Week Cooldown" }
quests[46769] = { id = 46769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheit macht Diebe", description = "Nicht alle Dämonen an dieser Küste trampeln herum, wo wir sie sehen können. Einige schleichen durch die Schatten und finden subtilere Wege, die Legion voranzubringen.\n\nIch habe das Verhalten kleinerer Dämonen beobachtet, der Wyrmzungen. Sie verbringen offenbar einige Zeit damit, nach mächtigen Gegenständen zu suchen. Wir können nicht zulassen, dass sie diese gegen uns verwenden.\n\nDie Wyrmzungen horten ihre Sachen in Truhen, die an der Verheerten Küste verteilt sind. Ich schlage vor, dass Ihr ihnen diese unrechtmäßig erworbenen Schätze wieder abnehmt.", sourceObjective = "Findet 3 verborgene Wyrmzungentruhen an der Verheerten Küste.", progress = "Habt Ihr die Wyrmzungentruhen gefunden?", completion = "Gute Arbeit. Es ist wichtig, dass wir mächtige Schätze von Dämonenhänden fernhalten.\n\nDämonen zu töten, ist nicht der einzige Weg, der Legion das Handwerk zu legen... wobei es allerdings viele gute Argumente für das klassische Gemetzel gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46772] = { id = 46772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Magierturm", description = "Gut gemacht, {name}. In Anerkennung aller hier kämpfenden Streitkräfte sind wir zusammengekommen, um den Bau des Magierturms zu vollenden.\n\nIhr müsst unsere Arbeit nur noch inspizieren und den Bau abschließen.", sourceObjective = "Schließt den Bau des Magierturms ab.", progress = "Inspiziert den Magierturm und schließt seinen Bau ab.", completion = "Dank unserer großen Mühen genießen wir jetzt einen Vorteil, von dem alle in den kommenden Tagen profitieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[46773] = { id = 46773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kommandozentrale", description = "Gut gemacht, {name}. In Anerkennung aller hier kämpfenden Streitkräfte sind wir zusammengekommen, um den Bau der Kommandozentrale zu vollenden.\n\nIhr müsst unsere Arbeit nur noch inspizieren und den Bau abschließen.", sourceObjective = "Schließt den Bau der Kommandozentrale ab.", completion = "Dank unserer großen Mühen genießen wir jetzt einen Vorteil, von dem alle in den kommenden Tagen profitieren können.", sourceObjectiveStatus = "unverified-source-field" }
