quests[46776] = { id = 46776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akazamzarak 1 Week Cooldown" }
quests[46777] = { id = 46777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute der Legionsrichter", description = "{class}t, danke für Eure Mühen. Unsere Truppen konnten dadurch weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nJe deutlicher Ihr das Schlachtfeld beherrscht, desto mehr Ressourcen können unsere Truppen erübrigen.", sourceObjective = "Sprecht mit Hauptmann Ruysantos an der Verheerten Küste, um Eure Belohnung zu erhalten.", completion = "Schlachtenfürst, danke für Eure Mühen. Unsere Truppen konnten dadurch weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nJe deutlicher Ihr das Schlachtfeld beherrscht, desto mehr Ressourcen können unsere Truppen erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46778] = { id = 46778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterentwicklung", description = "Während der Krieg gegen unsere Feinde voranschreitet, müssen auch wir uns weiterentwickeln.\n\nWir können jetzt neue Forschungen betreiben. Wendet Euch an Einar den Runenmagier, um die Ordenshalle zu verbessern.", sourceObjective = "Sucht Einar den Runenmagier auf.", completion = "Unsere Macht wächst.", sourceObjectiveStatus = "unverified-source-field" }
