quests[46789] = { id = 46789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterentwicklung", description = "Während der Krieg gegen unsere Feinde voranschreitet, müssen auch wir uns weiterentwickeln.\n\nWir können jetzt neue Forschungen betreiben. Wendet Euch an Archivar Zubashi, um die Ordenshalle zu verbessern.", sourceObjective = "Sucht Archivar Zubashi auf.", completion = "Unsere Macht wächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[46791] = { id = 46791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Winde verweht", sourceObjective = "Kehrt zum Mahlstrom zurück und sprecht mit Konsul Celestos.", completion = "Ich danke Euch für Euer Kommen, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[46792] = { id = 46792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Stürme", description = "Donneraan hat mich gebeten, Euch zum Thron der Vier Winde zu entsenden, weil er Eure Hilfe in einer bestimmten Angelegenheit benötigt.\n\nSprecht mich einfach an, wenn Ihr bereit seid aufzubrechen, <Scharfseher/Scharfseherin>.", sourceObjective = "Sprecht mit Konsul Celestos, wenn Ihr bereit seid, das Szenario \"Zorn der Stürme\" zu beginnen. Schließt das Szenario ab und kehrt dann zu Celestos zurück.", completion = "Jetzt, wo der Rat wiedervereint ist, wird die Ebene der Luft wieder mit geballter Wucht agieren!\n\nIch glaube, Windlord Donneraan möchte Euch eine Belohnung zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46793] = { id = 46793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Mage Tower - Buff Activation - Tracking Quest" }
quests[46794] = { id = 46794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Hofes", description = "Der dankbare Hof von Farondis hat Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Veridis Fallon in Azsuna.", completion = "Seid gegrüßt, Erzdruide {name}.\n\nSchon seit geraumer Zeit leistet Ihr unserem Prinzen und unserem Volk treue Dienste. Unsere Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46795] = { id = 46795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship - Azsuna" }
quests[46796] = { id = 46796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Hochbergs", description = "Die dankbaren Stämme des Hochbergs haben Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Ransa Graufeder am Hochberg.", completion = "Seid gegrüßt, Scharfseher {name}.\n\nSchon seit geraumer Zeit leistet Ihr unserem Volk treue Dienste. Unsere Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46797] = { id = 46797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Traumweber", description = "Die dankbaren Druiden der Traumweber haben Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Sylvia Hirschhorn in Val'sharah.", completion = "Seid gegrüßt, Erzdruide {name}.\n\nSchon seit geraumer Zeit leistet Ihr der Natur und unserem Volk treue Dienste. Unsere Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46798] = { id = 46798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Valarjar", description = "Die beeindruckten Vrykul der Valarjar haben Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Valdemar Sturmsucher in Sturmheim.", completion = "Seid gegrüßt, Hochlord {name}.\n\nSchon seit geraumer Zeit leistet Ihr Odyn als Held der Valarjar treue Dienste. Unsere Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46799] = { id = 46799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Nachtsüchtigen", description = "Die überaus dankbare Thalyssra hat Eure Anwesenheit erbeten. Sie möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit der Ersten Arkanistin Thalyssra in Suramar.", completion = "Seid gegrüßt, Meisterjäger {name}, Fremdling, Freund und Befreier.\n\nUnsere Dankbarkeit lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46800] = { id = 46800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Wächterinnen", description = "Die beeindruckten Wächterinnen haben Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Marin Klingenflügel in Azsuna.", completion = "Seid gegrüßt, Erzdruide.\n\nSchon seit geraumer Zeit leistet Ihr treue Dienste im Kampf gegen die Legion und bei der Unterstützung der Wächterinnen. Unsere Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46801] = { id = 46801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship - Val'sharah" }
quests[46802] = { id = 46802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Legionsrichter", description = "Eure treuen Truppen bei den Legionsrichtern haben Eure Anwesenheit erbeten. Man möchte Euch für Eure wertvolle Hilfe eine Belohnung überreichen.", sourceObjective = "Sprecht mit Hauptmann Ruysantos an der Verheerten Küste.", completion = "Seid gegrüßt, Meisterjäger.\n\nSchon seit geraumer Zeit leistet Ihr treue Dienste im Kampf gegen die Legion. Ihr seid fürwahr ein Symbol, das unsere Armeen vereint. Unsere Dankbarkeit dafür lässt sich kaum in Worte fassen.\n\nBitte nehmt also diese Trophäen und einen Teil der Kriegsbeute als Zeichen unserer Dankbarkeit. Je mehr Ihr uns helft, desto mehr können wir Euch überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46804] = { id = 46804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modegeschichte und die Philosophie des Stils", description = "Seid gegrüßt, {name}. Ich bin ein Modehistoriker, und ich möchte erstaunliche Fortschritte in Schneiderei, Lederverarbeitung und Schmiedekunst mit Euch teilen. Warum?\n\nEine wahre Legende bleibt nur so strahlend in Erinnerung, wie ihr umwerfendendes Erscheinungsbild auf dem Schlachtfeld es ermöglicht. Und mal ganz ehrlich... Das ist nicht gerade Eure Stärke.\n\nSprecht mich erneut an, wenn Ihr wissbegierig seid.", sourceObjective = "Lernt von Eliezer Hammerbart, wie Ihr Eure Kleidung mit dem \"angemessenen Flair\" versehen könnt.", completion = "Ich bin froh, dass ich Euch das Hammerbartsystem für Stil und Eleganz näherbringen konnte. Seid Ihr also bereit, in Eurem erwählten Beruf ein Vermächtnis zu hinterlassen, an das man sich erinnern wird?", sourceObjectiveStatus = "unverified-source-field" }
quests[46805] = { id = 46805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Betrügers", description = "Er war einst wie ein Bruder für mich. Dann hat er die Seele meiner Welt für seinen eigenen Machtgewinn eingetauscht. Er hat mein Volk durch die gesamte Sternenwelt gejagt und meinen Sohn in ein Monster verwandelt.\n\nJetzt ist er gekommen, um den finalen Angriff auf Azeroth zu überwachen und diese Welt wie so viele andere zu opfern.\n\nKil'jaeden.\n\nWir müssen sicherstellen, dass er uns dieses Mal nicht entkommt, {name}. Stürmt das Grabmal. Vernichtet diese Festung der Legion. Beendet die Herrschaft des Betrügers.", sourceObjective = "Betretet das Grabmal des Sargeras und besiegt Kil'jaeden.", progress = "Keine Gnade. Der Betrüger muss fallen.", completion = "Beim Anblick des Betrügers sind Tausende Jahre Hass durch mein Herz geschossen. Hass, der mich ergriffen und blind für alle Gedanken außer jenen an Rache gemacht hat.\n\nGlücklicherweise hat das Licht mir verdeutlicht, dass sich die Zukunft nicht an der Vergeltung, sondern an der Hoffnung ausrichten muss. Und auch Ihr mit Eurem Mut habt mir dies gezeigt, {name}.\n\nIn den letzten Momenten von Kil‘jaedens Leben musste ich die Vergangenheit zurücklassen. Nicht nur für mich, sondern auch für das Andenken an meinen Sohn.\n\nMein Geist und mein Verstand sind jetzt rein und fokussiert. Jetzt können wir Sargeras selbst bekämpfen. Jetzt werden wir die Legion auslöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46808] = { id = 46808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship - Highmountain" }
quests[46809] = { id = 46809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung verlorenen Wissens", description = "Es liegt im Wesen dieses uralten Folianten der Nachtelfen, neues Wissen zu suchen. Das könnte für die Erforschung Eurer Artefaktwaffe von großem Wert sein.\n\nDie Gelehrten in Eurer Ordenshalle würden bestimmt großen Nutzen aus ihm ziehen und womöglich neue Wege der Macht erschließen.\n\nIch würde vorschlagen, dass Ihr ihn sofort zu ihnen bringt. Im Kampf gegen die Legion können wir jeden Vorteil gebrauchen!", sourceObjective = "Sprecht mit dem Artefaktforscher in Eurer Klassenordenshalle.", completion = "Was habt Ihr heute mitgebracht, Todesgebieter?\n\n<Illanna untersucht den uralten Folianten.>\n\nDieses Buch ändert alles!", sourceObjectiveStatus = "unverified-source-field" }
quests[46810] = { id = 46810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab in die Schmiede", description = "Der Umhang ist zu zerfetzt, um ihn zu tragen, doch er kann in der Obliterumschmiede in Dalaran eingeäschert werden.", sourceObjective = "Bringt den zerfetzten Umhang des Gladiators zur Obliterumschmiede in Dalaran und benutzt die Schmiede, um ihn einzuäschern. Bringt das daraus resultierende Ergebnis zu Marschall Frazer in die Graufangenklave.", progress = "Habt Ihr in letzter Zeit die Schmiede besucht?", completion = "Wenn Ihr noch mehr unerwünschte Kriegsbeute macht, bringt sie einfach zum Einäschern zur Schmiede. Dann helfe ich Euch, stattdessen etwas Wünschenswerteres zu entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[46811] = { id = 46811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Brutmutter" }
quests[46812] = { id = 46812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachengeheimnisse", description = "<Die eisige Präsenz des Lichkönigs bemächtigt sich einmal mehr Eures Geistes.>\n\nArthas hat niemals die Beute gefunden, nach der er suchte, <Todesgebieter/Todesgebieterin>.\n\nSie gehört rechtmäßig uns.\n\nDie Drachen müssen wissen, wo die Ruhestätte eines der ihren liegt.\n\nFindet einen Bronzedrachen, einen Hüter der Geschichte. Zeigt keine Gnade.\n\n<Die Präsenz schwindet.>", sourceObjective = "Verhört Trizormu im Wyrmruhtempel in der Drachenöde und folgt dann dem Plan des Lichkönigs.", sourceObjectiveStatus = "unverified-source-field" }
quests[46813] = { id = 46813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verlorene Gletscher", description = "<Die Präsenz des Lichkönigs ist überwältigend.>\n\nWisst Ihr, warum der rote Drachenschwarm verhindern will, dass wir unsere Beute finden?\n\nDie Knochen eines roten Großdrachen strotzen nur so vor Lebensessenz, selbst wenn seit seinem Tod Jahrzehnte vergangen sind.\n\nIhr werdet seine Lebensessenz in Euch aufnehmen, sie verderben und sie dem Untod übergeben.\n\nUnd dann werdet Ihr einen Drachen wiederauferstehen lassen.\n\nFliegt jetzt nach Norden. Findet diesen Gletscher und Euer Schicksal.\n\n<Die Präsenz schwindet.>", sourceObjective = "Reist zum Verlorenen Gletscher.", completion = "<Der Riss im Eis unter dem Schnee ist sehr tief. Ihr spürt, wie die unheilige Kraft Euch durchwogt. Dies wäre der ideale Ort, um die Energie zu entfesseln und den Drachen zu erwecken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[46814] = { id = 46814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Frostwyrms" }
quests[46815] = { id = 46815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eredath, Juwel von Argus", description = "Die zerschmetterten Ruinen unter uns sind alles, was von Eredath übrig geblieben ist.\n\nWir nannten es einst das Juwel von Argus. Von hier aus haben meine Weggefährten des Triumvirats unser Volk in eine Blütezeit geführt. Aber das ist schon lange her.\n\n<Velen hält einen Moment inne.>\n\nKommt mit mir auf die Oberfläche. Wir werden jetzt mit der Suche nach der Krone des Triumvirats beginnen.", sourceObjective = "Begebt Euch mit Velen hinunter nach Eredath.", completion = "Als hätte der Kampf niemals aufgehört. Wie lange mussten sie wohl leiden?", sourceObjectiveStatus = "unverified-source-field" }
quests[46816] = { id = 46816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous", description = "Es muss noch viel getan werden, um diesen Alptraum zu beenden. Aber wir müssen uns erst sammeln, bevor wir die Aufmerksamkeit der Legion auf uns ziehen.\n\nIch konnte beim Absturz einen Signalkristall sichern. Damit lassen sich Transportsignale von der Xenedar anfordern.\n\nMit etwas Glück können wir damit auch eine Verbindung zwischen hier und Euren Truppen herstellen.", sourceObjective = "Verwendet den Signalkristall, um ein lichtgeschmiedetes Signal von der Vindikaar anzufordern.", completion = "Lothraxion ist ein alter Freund und großer Krieger. Wir können uns glücklich schätzen, ihn auf unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46817] = { id = 46817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niedergang der Höllenbestien" }
quests[46818] = { id = 46818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wehrlos und verängstigt", description = "Das ist die Schlacht, die tobte, während ich auf die Genedar wartete. So viele wollten sich mir anschließen, aber Kil'jaeden hat ihnen noch mehr in den Weg gestellt.\n\nMeine Leute wurden gnadenlos abgeschlachtet.\n\nUm unseren Rückzug zu sichern, habe ich angeordnet, die Verteidigung der Arena zu aktivieren. Es ist ihnen ganz offensichtlich nicht gelungen.\n\nUm die Schlacht noch zu gewinnen und diesen Seelen Frieden zu schenken, müssen wir ihre Aufgabe zu Ende bringen. Findet einen Weg, die Pylonen zu aktivieren.", sourceObjective = "Sammelt gestohlene Pylonenkerne von Gegnern am Triumviratsbruch ein und verwendet sie, um 3 uralte Pylonen zu aktivieren.", completion = "Das Blatt wendet sich. Wir müssen weitermachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46819] = { id = 46819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrecked Cart" }
quests[46820] = { id = 46820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
