quests[46822] = { id = 46822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Auslese" }
quests[46823] = { id = 46823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowstrike and Thunderstrike" }
quests[46824] = { id = 46824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowstrike and Thunderstrike Anniversary" }
quests[46825] = { id = 46825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matschepatsche" }
quests[46826] = { id = 46826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battleplate of the Silver Hand" }
quests[46827] = { id = 46827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit den Schatten verschmelzen", description = "Wir sollten uns wieder dem Rest des Rats anschließen und ihnen berichten, was wir an diesem Tag erreicht haben. Kehrt zu uns zurück, wann immer es Euch beliebt. Wir werden auf Euch warten.", sourceObjective = "Kehrt zur Halle der Schatten zurück und sucht Lord Jorach Rabenholdt auf.", completion = "Wir haben über Eure Erfolge in der letzten Zeit gesprochen, {name}. Wir bewegen uns in den Schatten und das wird oft als selbstverständlich angesehen. Doch ohne uns hätten es die Legionsrichter mit weitaus mehr mächtigen Dämonen zu tun.\n\nWir brauchen den Ruhm nicht. Wir ernten den Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[46829] = { id = 46829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarmissbrauch" }
quests[46830] = { id = 46830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield" }
quests[46832] = { id = 46832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aalgens Posten", description = "Ihr wollt Gebiete auf diesem Dreckshaufen von einer Insel halten, richtig? Richtig. Dann müssen wir mit den Lagern weiter draußen Kontakt aufnehmen.\n\nIch kenne einen Genossen namens Heidirk. Ein quirliger Typ, mag das Getümmel. Hat sich mit seinen Drachen zur östlichen Küste aufgemacht.\n\nSucht nach ihm und erinnert ihn daran, dass er mir noch das eine oder andere Getränk schuldig ist!", sourceObjective = "Sprecht mit Heidirk dem Schuppenhüter an Aalgens Posten.", completion = "Kammerer hat Euch geschickt? Der lässt auch keinen Krug verkommen, das muss man ihm lassen. Aber wenn er behauptet, dass ich ihm etwas schulde, dann ist das gelogen!\n\nKeine Sorge, ich werde diese Position mit meinen Drachen halten. Aber wir müssen noch mehr Bereiche dieser Küste sichern, wenn Eure Kampagne siegreich sein soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[46833] = { id = 46833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Natur" }
quests[46834] = { id = 46834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khazaduum, der Erste seiner Art", description = "Die Argunitmatrix, die diesen Teil von Eredath mit Energie versorgt hat, wurde von einer riesigen Bestie zerschmettert. Ein derartiges Wesen hatten wir noch nie erblickt.\n\nEr nannte sich Khazaduum und war einer der treuesten Diener der Legion. Er hatte sich freiwillig einer experimentellen Umwandlung unterzogen, um der Erste seiner Art zu sein. Mit seinem Eingreifen in die Schlacht war sie entschieden.\n\nAls Preis nahm er sich den Argunitschlüsselstein der zerschmetterten Matrix. Holt ihn zurück, damit wir dieses Blutvergießen endlich beenden können.", sourceObjective = "Besorgt den Argunitschlüsselstein vom Echo von Khazaduum.", progress = "Bitte, sie sollen nicht noch länger leiden.", completion = "Ich kann nicht alles hier geschehene Unrecht wiedergutmachen, aber das war mir dennoch ein Trost.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[46835] = { id = 46835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of a Frightened World Tracking" }
quests[46839] = { id = 46839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Finsternis", description = "Ich fürchte, es ist nur eine Frage der Zeit, bis sie wissen, dass wir hier sind.\n\nWir müssen sofort mit den Vorbereitungen beginnen.", sourceObjective = "Begleitet Hochexarch Turalyon.", completion = "Dann beginnt es also.", sourceObjectiveStatus = "unverified-source-field" }
quests[46840] = { id = 46840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gefangenen mehr", description = "Hatuuns Leute haben harte Zeiten hinter sich. Sie werden immer weiter dezimiert. Die Annihilanlords reißen sie aus ihrer Zuflucht, um sie zu willenlosen Sklaven in den Gruben zu machen. Dort müssen sie schuften und leiden, bis sie irgendwann sterben dürfen.\n\nKümmert Euch um die Gefangenen und befreit sie von ihren Fesseln. Zeigt unseren Verbündeten, dass wir die Brennende Legion gemeinsam bekämpfen werden.", sourceObjective = "Rettet 10 sinistre Sklaven aus den Annihilangruben.", completion = "Hatuuns Leute werden zu schätzen wissen, was Ihr heute für sie getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[46841] = { id = 46841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verringerte Bedrohung", description = "Hatuun und seine Leute werden im Laufe der Zeit ihre Verbitterung ablegen und zu wertvollen Verbündeten werden. Aber ihr Vertrauen müssen wir uns erst verdienen.\n\nEr sagt, dass sein Dorf von einem Dämon namens Aggonar und seinen grausamen Artgenossen heimgesucht wird.\n\nWir müssen diese Feinde ausmerzen, bevor wir uns auf die Suche nach Alleria und den anderen machen können.\n\nDer Häuptling hat uns sein Horn geliehen. Verwendet es, um damit für seine Leute Rache an den Leutnants des Dämons zu nehmen, während ich einen Weg in den Unterschlupf von Aggonar vorbereite.", sourceObjective = "Tötet Kar'aaz, Xeth'tal und Magraloth in den Annihilangruben.", progress = "Habt Ihr die Bedrohung ausschalten können?", completion = "Jetzt, wo ihre Lords eingeäschert sind, können wir sie direkt im Herzen ihrer Macht angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46842] = { id = 46842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stich ins Herz", description = "Diese Gruben haben unseren neuen Verbündeten schon sehr viel Leid gebracht. Die Dämonen machen Jagd auf die armen Seelen und foltern sie nur zum Vergnügen.\n\n<Turalyon schüttelt angewidert seinen Kopf und richtet dann seinen Blick auf die Kreatur vor ihm.>\n\nEs ist an der Zeit, sie für ihre Grausamkeiten zahlen zu lassen und diesem lichtvergessenen Ort wieder Hoffnung zu schenken.\n\nWir schlagen auf Euer Zeichen los, {name}.", sourceObjective = "Tötet Aggonar.", completion = "Dieser Sieg ist nur der erste in einer langen Reihe, Meisterjäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[46843] = { id = 46843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Vindikaar", description = "Dieser Grubenlord wird unseren neuen Verbündeten keine Sorgen mehr bereiten.\n\n<Turalyon runzelt die Stirn.>\n\nZumindest so lange, bis ein anderer seinen Platz einnimmt. Wenn ich etwas in diesem endlosen Krieg gegen die Legion gelernt habe, ist es, jeden Sieg entsprechend zu würdigen.\n\nKommt, nutzen wir den Augenblick, um uns bei Eurem Schiff zu sammeln. Alleria und ich mussten lange auf das Wiedersehen mit unserem Sohn warten.", sourceObjective = "Kehrt zur Vindikaar zurück.", completion = "Unsere Abwesenheit hat Arator geschmerzt. Wir waren uns dessen bewusst, aber wir mussten sichergehen, dass er in Sicherheit ist, während wir gegen die Legion kämpfen.\n\nJetzt, wo wir wieder vereint sind, werden wir uns nicht mehr trennen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46844] = { id = 46844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kathedrale der Ewigen Nacht: Herrin der Klingen" }
quests[46845] = { id = 46845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Racheposten", description = "Auf dem Weg hierher bin ich einem Trupp Dämonenjäger begegnet, die Richtung Nordwesten zum Racheposten unterwegs waren. Ihr könnt Euch darauf verlassen, dass die Legion versuchen wird, sie am Aufbau einer Stellung an der Front zu hindern.\n\nIch habe mit einer Elfe namens Izal Weißmond gesprochen. Sie war nicht gerade herzlich, aber sie wäre Euch bestimmt dankbar, wenn Ihr die Illidari unterstützt... auch wenn sie es vielleicht nicht zugibt.", sourceObjective = "Besiegt die Legion am Racheposten und erstattet Izal Weißmond Bericht.", completion = "Die Illidari verschwenden keine Zeit mit Glückwünschen. Es gibt noch mehr zu tun, und Ihr seid derjenige, der dazu imstande ist.\n\nAlso bewegt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[46846] = { id = 46846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wort des Zul", description = "Ich hab 'ne einfache Aufgabe für Euch. Unser lieber Prophet Zul will 'n paar bestimmt'n Leuten im Hafen Nachrichten zukomm' lass'n. \n\nUn' er will, dass Ihr sie überbringt.\n\nKeine Ahnung, warum er sie Euch nich' hat ausliefern lass'n, als Ihr das erste Ma' hier wart. Aber der Prophet is' dafür bekannt, seine Vision' nich' mit allen zu teil'n.", sourceObjective = "Bringt die Worte des Zul zu verschiedenen Personen im Hafen von Zandalar.", progress = "Habt Ihr Eure ganz'n Lieferungen erledigt?", completion = "Ah, auf Euch is' also doch Verlass, {race}. Vielleicht kann man Euch mit noch wichtigeren Aufgaben betreu'n. Mit der Müllentsorgung zum Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[46865] = { id = 46865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kathedrale der Ewigen Nacht: Mutter der Flammen" }
quests[46866] = { id = 46866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folterkammer" }
quests[46867] = { id = 46867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kathedrale der Ewigen Nacht: Teufelsbestie" }
quests[46868] = { id = 46868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kathedrale der Ewigen Nacht: Die teuflischen Toten" }
quests[46869] = { id = 46869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kathedrale der Ewigen Nacht: Verführerin der Pein" }
quests[46870] = { id = 46870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Command Center - Buff Activation - Tracking Quest" }
quests[46871] = { id = 46871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Nether Disruptor - Buff Activation - Tracking Quest" }
quests[46904] = { id = 46904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Kommandozentrale", sourceObjective = "Gut gemacht, jetzt kann ich Euch einen Segen verleihen, solange die Kommandozentrale aktiviert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[46924] = { id = 46924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte des Wolfs", description = "Goldrinn hat wirklich keine Zeit verstreichen lassen, bevor er von hier abgehauen ist, was?\n\nSchauen wir mal, ob wir ihn draußen finden können.", sourceObjective = "Findet Goldrinn außerhalb von Sturmgrimms Grabhügel.", progress = "Es tut gut, aus dem Grabhügel befreit zu sein.", completion = "Wir müssen den Hain der Träume warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46926] = { id = 46926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erpressung", description = "Wo bleib'n die Wachen? \n\nPrinzessin Talanji hat König Rastakhan überzeugt, Fremde in den Hafen zu lass'n. Zum ersten Mal seit Jahrhunderten dürf'n Nichttrolle sich an unserer Küste aufhalten un' ihre Waren feilbiet'n.\n\nUn' jetzt glaub'n die Trolle der niederen Stämme, dass sie sich diese Händler vorknöpf'n können?\n\nDieses Verhalten werd ich nich' tolerier'n. Ich werd untersuch'n, warum die Händler nich' beschützt werd'n. Un' Ihr zieht derweil durch den Basar un' tötet alle Schläger, die Ihr find'n könnt. \n\nErteilt ihnen 'ne Lektion.", sourceObjective = "Tötet 15 Hafengrobiane.", completion = "Ich danke Euch. Ich glaub, dass jemand von der Horde für Gerechtigkeit gesorgt hat, war umso angemess'ner.\n\nDass wir unseren Hafen so ungeschützt gelass'n hab'n, macht mir aber große Sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[46927] = { id = 46927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strafaktion in Tal'aman", description = "Also, Zolani geht das alles völlig falsch an. Wenn Ihr die Aufmerksamkeit der Amani oder von jemand andrem erreg'n wollt, müsst Ihr ihre Anführer ausschalt'n.\n\nGeht nach Tal'aman un' sucht nach dem riesigen Gong. Fordert vier ihrer Schüler zum Kampf heraus und schlachtet sie ab.", sourceObjective = "Fordert 4 Jünger der Amani heraus.", progress = "Diese Waldtrolle könn' echt fies sein.", completion = "Es wird nich' lang dauern, bis diese Jünger durch neue ersetzt werd'n. Hoffentlich lern' die nächst'n was aus der Vergangenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[46928] = { id = 46928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strafaktion in Tal'farrak", description = "Der Stamm der Sandwüter war vielleicht in die Verbrech'n hier verwickelt, aber es is' vor allem ihr Irrglaube, der sie solche Dinge mach'n lässt. Geht nach Tal'farrak, schlagt dort den Gong un' stellt Euch der Hydra, die sie sich als so 'ne Art heiliges Haustier halt'n.\n\nBringt mir die Zung'n von diesem Ding.", sourceObjective = "Beschafft Gahz'ragons Zungen.", progress = "Habt Ihr die Zung'n?", completion = "Hahaha. Man kann viel über 'n Stamm erfahr'n, wenn man sich ansieht, was sie anbet'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[46929] = { id = 46929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschreckung", description = "General Jakra'zet hatte den Befehl, diesen Ort zu beschütz'n. Mit Wachen. Aber ich seh nichts davon.\n\nJakra'zet is' ein störrischer General un' ich hab schon 'ne Weile 'n Auge auf ihn.\n\nWie auch immer, wir müssen dies'n nied'ren Stämmen, die in der Stadt herrsch'n, 'ne Nachricht schicken, die sie versteh'n.\n\nIch beauftrage Euch hiermit, Köpfe sammeln zu geh'n.\n\nGeht nach Tal'farrak un' nach Tal'aman und sammelt 'nen ordentlichen Hauf'n Köpfe.", sourceObjective = "Sammelt 6 Amaniköpfe in Tal'aman und 6 Sandwüterköpfe in Tal'farrak.", progress = "Trollpolitik is' mehr wie 'n blutiger Kampfsport.", completion = "Wenn Besucher die Sprache Eurer Gesetze nich' versteh'n, muss man sie ihnen eben in 'ner Sprache erklären, die sie versteh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[46930] = { id = 46930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rastakhan", description = "Ihr steht vor General Jakra'zet, Herr über die Armeen von Zandalar, Vollstrecker auf den Meeren un' Herold des Krieges.\n\nUnd ich kann Euch nich' leid'n. \n\nIch hab Jahre gebraucht, um meine Stellung hier zu erhalt'n, nachdem Eure Horde mein Volk zu Staub zermalmt hat. Ihr werdet nich' zunichtemach'n, was ich mir hier aufgebaut hab.\n\nIch werd mitanseh'n, wie Ihr vor König Rastakhan kniet. Und ich werd Euch flehen seh'n, wenn er mich Euren Kopf als Trophäe abschlag'n lässt. Euren Leichnam werd ich ins Ödland von Vol'dun schleudern.\n\nIhre \"Hoheit\" wird vielleicht protestier'n... aber noch is' sie nich' Königin.\n\nKommt. Lasst uns Eurem Schicksal entgegenflieg'n.", sourceObjective = "Trefft Euch mit König Rastakhan.", progress = "Willkommen, Champion der Horde. Ich bin König Rastakhan, Lord von Zandalar un' seinen Einwohnern.", completion = "Ich hab von Euren Taten gehört, noch bevor Ihr auch nur einen Fuß auf mein Land gesetzt habt. Wird Zeit, dass wir red'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[46931] = { id = 46931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimme der Horde", description = "Eure Horde is' mächtig geword'n und stellt sogar manche Trollreiche in den Schatt'n.\n\nFür die Rettung meiner Tochter habt Ihr Euch das Recht verdient, Euch in meiner Stadt aufzuhalt'n.\n\nUnd weil meine Tochter solch'n Gefallen an Euch gefund'n hat, dürft Ihr Euch mit ihr im Großen Siegel unter uns treff'n. Die Diener untersteh'n ab sofort Euch.\n\nTalanji scheint mir aufgeregt weg'n dem, was sie mit Euren Leut'n vorhat. Was auch immer es is', ich freu mich schon drauf, mich später darüber zu amüsier'n.\n\nZolani wird Euch 'n Weg nach unten zeig'n, über den Ihr auch sicher ankommt.", sourceObjective = "Gründet Eure Botschaft.", completion = "Willkommen im Tresor der Könige, {name}. Wir bring'n alle neuen Schätze, die wir find'n, in dies'n Raum. Un' das nur wegen dem Ding da an der Wand.\n\nDas Ding is' älter als alles andre, was wir kenn'n. Ich hoff, dass ich eines Tages herausfind, was es damit auf sich hat.\n\nAber ich will Euch nich' aufhalt'n. Ihr habt sicher dringende Sachen mit Prinzessin Talanji zu besprech'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[46932] = { id = 46932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch mehr Verderbnis" }
quests[46933] = { id = 46933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelrglrglrglrgl" }
quests[46935] = { id = 46935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten der Sentinax", description = "Dieses Gerät scheint Nachrichten von dem großen Dämonenschiff über uns weiterzuleiten. Leider ist es defekt und reagiert nicht mehr.\n\nVielleicht weiß jemand an der Retterklippe mehr über diese Geräte.", sourceObjective = "Bringt das defekte Sentinaxsignal zu Kriegsmagierin Kath'leen an der Retterklippe.\n\nBereitgestellter Gegenstand:", completion = "Die Legion nutzt diese Signalgeber, um mit ihrer Flotte dort oben zu kommunizieren. Wenn wir noch mehr davon finden könnten...", sourceObjectiveStatus = "unverified-source-field" }
quests[46938] = { id = 46938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allein im Abgrund", description = "Champion, wir werden das gleiche Schicksal wie die Armee des Lichts erleiden, wenn die Legion diese infernalische Waffe auf uns abfeuert.\n\nWir müssen uns in das Belagerungslager unten begeben und sie zerstören, solange wir die Möglichkeit dazu haben!", sourceObjective = "Sprecht mit Großkonstrukteur Romuul, um von Bord der Vindikaar zu gehen.", completion = "Willkommen auf Argus, der Heimatwelt der Brennenden Legion.", sourceObjectiveStatus = "unverified-source-field" }
quests[46939] = { id = 46939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monk Finale" }
quests[46940] = { id = 46940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nutzung verlorenen Wissens", description = "Ich weiß nicht, ob Ihr schon begreift, was dieser Foliant für uns bedeutet. Damit können wir nämlich noch mehr Artefaktwissen sammeln und zum Einsatz bringen!\n\nLasst uns sofort anfangen. Auf Euren Befehl nehmen wir die Forschungen wieder auf.", sourceObjective = "Beginnt einen Arbeitsauftrag für Forschung.", completion = "Ausgezeichnet! Kommt in einer Weile vorbei, um Euch über unsere Fortschritte zu informieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[46941] = { id = 46941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad voraus", description = "<Velen starrt einen langen Augenblick an der Arena vorbei.>\n\nWir müssen weitermachen, aber ich spüre, dass Eredath noch lange nicht fertig mit uns ist. Wir sollten diese relative Sicherheit nutzen, solange wir noch können.\n\nIch werde ein Signal absetzen, damit die Vindikaar unseren Standort anpeilen kann. Romuul wird uns die Mittel schicken, die wir für die Rückkehr zur Vindikaar benötigen, wenn es die Lage erfordert.", sourceObjective = "Fordert ein lichtgeschmiedetes Signal an.", progress = "Es gibt noch viel herauszufinden, {name}. Argus hat uns nicht vergessen.", completion = "Der Weg voran ist frei und wir haben die Armee des Lichts an unserer Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[46942] = { id = 46942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Macht" }
quests[46945] = { id = 46945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Si'vash" }
quests[46946] = { id = 46946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab in die Schmiede", description = "Der Umhang ist zu zerfetzt, um ihn zu tragen, doch er kann in der Obliterumschmiede in Dalaran eingeäschert werden.", sourceObjective = "Bringt den zerfetzten Umhang des Gladiators zur Obliterumschmiede in Dalaran und benutzt die Schmiede, um ihn einzuäschern. Bringt das daraus resultierende Ergebnis zu Violetta Schattenheiler in Windläufers Zuflucht.", progress = "Ihr habt vor Kurzem die Schmiede besucht, was?", completion = "Wenn Ihr noch mehr unerwünschte Kriegsbeute macht, bringt sie einfach zum Einäschern zur Schmiede. Dann helfe ich Euch, stattdessen etwas Wünschenswerteres zu entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[46947] = { id = 46947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutallus" }
