quests[46957] = { id = 46957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Zuldazar", description = "Champion der Horde, willkommen in Zuldazar, der Hauptstadt des Zandalariimperiums, dem Juwel aller Trollzivilisationen.\n\nReitet doch an meiner Seite, damit wir uns besprech'n können, ohne von neugierig'n Ohren belauscht zu werd'n.", sourceObjective = "Reitet mit Prinzessin Talanji.", progress = "Reitet Ihr mit mir?", completion = "Das is' weit genug, Hordegesindel.", sourceObjectiveStatus = "unverified-source-field" }
